def choose_move(observation):
    x = observation.get("self_position", {}).get("x", 0)
    y = observation.get("self_position", {}).get("y", 0)

    grid_w = observation.get("grid_width", 0)
    grid_h = observation.get("grid_height", 0)

    resources = observation.get("resources", [])
    if isinstance(resources, list) and resources:
        nearest = None
        bestd = None
        for r in resources:
            rx = r.get("x", x)
            ry = r.get("y", y)
            d = (rx - x) * (rx - x) + (ry - y) * (ry - y)
            if bestd is None or d < bestd:
                bestd = d
                nearest = (rx, ry)
        if nearest is not None:
            dx = nearest[0] - x
            dy = nearest[1] - y
            if dx != 0:
                dx = int(dx / abs(dx))
            if dy != 0:
                dy = int(dy / abs(dy))
            if dx != 0 or dy != 0:
                return [dx, dy]

    enemies = observation.get("opponent_position", {})
    if isinstance(enemies, dict) and enemies:
        ex = enemies.get("x", x)
        ey = enemies.get("y", y)
        dx = ex - x
        dy = ey - y
        if dx != 0:
            dx = int(dx / abs(dx))
        if dy != 0:
            dy = int(dy / abs(dy))
        if dx != 0 or dy != 0:
            return [dx, dy]

    obstacles = observation.get("obstacles", [])
    if isinstance(obstacles, list) and obstacles:
        # try to move away from the closest obstacle
        nearest = None
        bestd = None
        for o in obstacles:
            ox = o.get("x", x)
            oy = o.get("y", y)
            d = (ox - x) * (ox - x) + (oy - y) * (oy - y)
            if bestd is None or d < bestd:
                bestd = d
                nearest = (ox, oy)
        if nearest is not None:
            dx = x - nearest[0]
            dy = y - nearest[1]
            if dx != 0:
                dx = int(dx / abs(dx))
            if dy != 0:
                dy = int(dy / abs(dy))
            if dx != 0 or dy != 0:
                return [dx, dy]

    # stay within grid
    if grid_w and grid_h:
        nx = max(0, min(grid_w - 1, x))
        ny = max(0, min(grid_h - 1, y))
        if nx != x or ny != y:
            dx = nx - x
            dy = ny - y
            if dx != 0:
                dx = int(dx / abs(dx))
            if dy != 0:
                dy = int(dy / abs(dy))
            return [dx, dy]

    # fallback: do nothing
    return [0, 0]
